import{_ as e,C as l,o as a,c as A,j as r,a as o,b as p,w as n,E,a3 as d,a4 as i}from"./chunks/framework.DyX1TuK3.js";const C=JSON.parse('{"title":"我們怎麼跟 AI 一起做出這個產品","description":"","frontmatter":{},"headers":[],"relativePath":"collab.md","filePath":"collab.md"}'),g={name:"collab.md"};function B(I,t,h,u,b,c){const s=l("Mermaid");return a(),A("div",null,[t[1]||(t[1]=r("h1",{id:"我們怎麼跟-ai-一起做出這個產品",tabindex:"-1"},[o("我們怎麼跟 AI 一起做出這個產品 "),r("a",{class:"header-anchor",href:"#我們怎麼跟-ai-一起做出這個產品","aria-label":'Permalink to "我們怎麼跟 AI 一起做出這個產品"'},"​")],-1)),t[2]||(t[2]=r("p",null,[r("em",null,"本文寫給團隊的非技術夥伴,說明工程端怎麼與 AI 協作。")],-1)),t[3]||(t[3]=r("blockquote",null,[r("p",null,"這份指南回答兩個問題:工程端「一人 + AI」實際上怎麼運作? 以及 — 你不寫程式,也能把同一套方法用在自己的工作上嗎?(可以,見第 6 節)")],-1)),t[4]||(t[4]=r("hr",null,null,-1)),t[5]||(t[5]=r("h2",{id:"_1-一天的開發循環長什麼樣",tabindex:"-1"},[o("1. 一天的開發循環長什麼樣 "),r("a",{class:"header-anchor",href:"#_1-一天的開發循環長什麼樣","aria-label":'Permalink to "1. 一天的開發循環長什麼樣"'},"​")],-1)),t[6]||(t[6]=r("p",null,"每個功能、每個修正,都走同一個圈:",-1)),(a(),p(d,null,{default:n(()=>[E(s,{id:"mermaid-18",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20A%5B%22%F0%9F%92%AC%20%E7%94%A8%E7%99%BD%E8%A9%B1%E6%8F%8F%E8%BF%B0%E9%9C%80%E6%B1%82%E6%88%96%E5%95%8F%E9%A1%8C%22%5D%20--%3E%20B%5B%22%F0%9F%A4%96%20AI%20%E5%88%86%E6%9E%90%20%C2%B7%20%E9%81%B8%E9%A0%85%E8%A1%A8(A%2FB%2FC)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%F0%9F%A7%AD%20%E4%BA%BA%E9%81%B8%E6%96%B9%E5%90%91(%E6%88%96%E8%AA%AA%E3%80%8C%E9%83%BD%E4%B8%8D%E5%B0%8D%2C%E6%88%91%E8%A6%81%E7%9A%84%E6%98%AF%E2%80%A6%E3%80%8D)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E2%9A%99%EF%B8%8F%20AI%20%E5%AF%A6%E4%BD%9C%20%2B%20%E8%B7%91%E8%87%AA%E5%8B%95%E6%B8%AC%E8%A9%A6%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%F0%9F%91%80%20%E4%BA%BA%E7%9C%8B%E7%95%AB%E9%9D%A2%20%2F%20%E7%9C%8B%E6%95%B8%E6%93%9A%E9%A9%97%E6%94%B6%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%F0%9F%9A%80%20%E4%B8%8A%E7%B7%9A(%E9%83%A8%E7%BD%B2%E5%BE%8C%E5%86%8D%E9%A9%97%E4%B8%80%E6%AC%A1)%22%5D%0A%20%20%20%20F%20-.%20%E4%B8%8B%E4%B8%80%E5%80%8B%E9%9C%80%E6%B1%82%20.-%3E%20A%0A%20%20%20%20classDef%20h%20fill%3A%23f26f21%2Cstroke%3A%23d4570c%2Ccolor%3A%23000%0A%20%20%20%20class%20B%2CD%20h%0A"})]),fallback:n(()=>[...t[0]||(t[0]=[o(" Loading... ",-1)])]),_:1})),t[7]||(t[7]=i('<p><strong>真實案例走一圈</strong> — 搜尋結果分數擠成一團那次:</p><ol><li>人(貼截圖):「分數都太近(65/65/62/60/59…),看不出差別。有沒有辦法拉開?」</li><li>AI 回三個方案:① 按真實差距重新攤開 ② 純等差排列 ③ 改用等級標籤不顯示數字 — 各附優缺點</li><li>人:「用 ①」</li><li>AI 改完、測試通過、部署</li><li>人 reload 畫面確認:分數從擠成一團變成 65 → 30 的清楚梯度 ✓</li></ol><p>整圈不到一小時。關鍵不是 AI 寫得快,是<strong>每一步都有人的判斷在裡面</strong>。</p><hr><h2 id="_2-人在做什麼-不是按-enter-而已" tabindex="-1">2. 人在做什麼?(不是按 Enter 而已) <a class="header-anchor" href="#_2-人在做什麼-不是按-enter-而已" aria-label="Permalink to &quot;2. 人在做什麼?(不是按 Enter 而已)&quot;">​</a></h2><p>AI 負責產出,人負責五件事:</p><p><strong>① 選方向</strong> — AI 善於列選項,不善於替你決定要什麼。 介面該往哪裡導、功能要做到多深,這類問題 AI 會給分析,但拍板的是人。</p><p><strong>② 給品味</strong> — 產品的「對味」只有人知道。 例:首頁的示範查詢句要選哪幾句?人給的標準是「戲劇張力為主、適用面愈廣愈好」—— 這種判斷 AI 給不出來,但給了標準之後,AI 可以快速產出一批讓人挑。</p><p><strong>③ 抓錯</strong> — AI 給的永遠是「能跑的解法」,人守的是「對的原則」。 例:AI 曾判斷海報壞圖應該全面改抓外部資料庫;人指出真正原因是頁面延遲載入, 並重申資料原則「官方來源優先、外部補位」。AI 修正後問題消失。 另一例:AI 寫的對外文件裡,有些「當初為什麼這樣選」是它自己合理化補的 —— 人看出來、要求逐條對帳,把推測換成真實理由。<strong>對 AI 的輸出保持「這是真的嗎?」的習慣,是協作裡最重要的肌肉。</strong></p><p><strong>④ 踩煞車</strong> — 不是每個提案都該直接做。 重要改動先要求「寫成計畫/草稿,討論完再動手」;文件要對外發布前,先列「即將公開的內容清單」逐項確認。 AI 動作很快,煞車踏板在人腳下。</p><p><strong>⑤ 驗收</strong> — 用看得懂的方式驗,不用看程式。 貼一張截圖問「這裡怪怪的?」、開 demo 網址實際操作、看評測分數有沒有變好。 驗收的語言是畫面和數據,不是程式碼。</p><hr><h2 id="_3-為什麼不會亂掉-—-護欄" tabindex="-1">3. 為什麼不會亂掉 — 護欄 <a class="header-anchor" href="#_3-為什麼不會亂掉-—-護欄" aria-label="Permalink to &quot;3. 為什麼不會亂掉 — 護欄&quot;">​</a></h2><p>把 AI 想成<strong>動作很快、但會很有自信地犯錯的新人</strong>。新人需要 code review,AI 也是 —— 只是我們把 review 盡量自動化:</p><table tabindex="0"><thead><tr><th>護欄</th><th>白話</th></tr></thead><tbody><tr><td>自動測試</td><td>每次改動跑 175 個檢查,壞了擋下來</td></tr><tr><td>提交關卡</td><td>程式碼進版本庫前自動掃:格式、密鑰外洩、甚至「介面文案不准寫死」</td></tr><tr><td>評分閉環</td><td>搜尋品質有客觀分數,每輪改動跑分 —— 贏的留、輸的回滾,不憑感覺</td></tr><tr><td>決策紀錄</td><td>重要技術轉向都寫下「背景、選項、理由」,AI 之後不會亂動既有決策</td></tr><tr><td>部署紀律</td><td>一律走版本庫部署,出事可以一鍵回滾、查得到是哪次改動</td></tr></tbody></table><p>人不需要看懂每一行程式 —— 但這些護欄確保「沒人看的那些行」也有東西在把關。</p><hr><h2 id="_4-難題怎麼一起拆" tabindex="-1">4. 難題怎麼一起拆 <a class="header-anchor" href="#_4-難題怎麼一起拆" aria-label="Permalink to &quot;4. 難題怎麼一起拆&quot;">​</a></h2><p>第 5 節講的是「拿到新需求怎麼拆」;這一節相反 —— <strong>卡住、AI 一直繞圈時</strong>怎麼辦。 這種時候 AI 很會「看起來很努力地亂試」,而<strong>人的提問品質決定出口</strong>。 有一套順序可以照走:</p><p><strong>① 先停手,別讓它一直試</strong> 連續幾輪沒進展,代表方向錯了,再試十次也一樣 —— 還會把問題愈攪愈亂。先喊停,回到診斷。</p><p><strong>② 要它先重現、再縮範圍</strong> 「這個問題每次都會發生,還是偶爾?」「拿掉一半,還在不在?」 沒有穩定重現、沒有縮小範圍之前,所有的修都只是猜。</p><p><strong>③ 逼它講假設,而且假設要能被推翻</strong> 「你覺得是什麼造成的?如果是,我們要怎麼驗證?」 講不出可以驗證的假設 = 還在亂槍打鳥,不要讓它動手改。</p><p><strong>④ 用二分法切因果</strong> 這是當時的轉機。評測接本地 AI 服務連續不穩,AI 的修法一直繞圈,直到換成這個問法:</p><blockquote><p>「先分清楚:是累積吃了三碗飯才飽,還是第三碗飯本身有問題?」</p></blockquote><p>一刀把問題切兩半 —— 是「累積狀態」造成的,還是「特定輸入」造成的? 範圍砍半,方向立刻清楚。</p><p><strong>⑤ 一次只改一個地方,改完馬上驗</strong> 同時改三處,就算好了也不知道是哪個的功勞、哪個其實沒用。一次一變因,因果才乾淨。</p><p><strong>⑥ 還是卡住,就換層次問</strong> 別在同一層鑽牛角尖。兩個最有效的跳脫:</p><ul><li><strong>給參照</strong>:「成熟的開源工具是怎麼解同一件事的?」比「你再想想」有效十倍 —— 借鑑勝過硬想。</li><li><strong>退一步</strong>:「我們是不是問錯問題了?」有時卡住是因為題目本身設錯。</li></ul><p><strong>⑦ 把誤判寫下來</strong> 每次「以為是 A 結果是 B」都照實記進決策紀錄 —— 否則 AI(跟人)過幾天會繞回同一個坑。</p><blockquote><p>一句話總結:<strong>卡住時,不是更用力,是更會問。</strong> 停手 → 重現縮範圍 → 可證偽假設 → 二分切因果 → 一次一變因 → 換層次借參照 → 記錄誤判。</p></blockquote><hr><h2 id="_5-拿到一個大需求-怎麼拆給-ai" tabindex="-1">5. 拿到一個大需求,怎麼拆給 AI <a class="header-anchor" href="#_5-拿到一個大需求-怎麼拆給-ai" aria-label="Permalink to &quot;5. 拿到一個大需求,怎麼拆給 AI&quot;">​</a></h2><p>「幫我做一個搜尋功能」這種需求,直接丟給 AI 會得到一坨能跑但你看不懂、改不動的東西。 先自己拆過一輪,再交手,品質天差地遠。拆解四步:</p><p><strong>① 先講清楚「做完長什麼樣」</strong> 不是「做搜尋」,而是「使用者打一句話 → 看到一排相關的片卡 → 每張有分數」。 能描述出「驗收時我會看到什麼」,需求才算想清楚。</p><p><strong>② 拆成可以「一個一個驗」的小塊</strong> 搜尋 = (a) 把片變成可比對的資料 →(b) 把查詢比對出候選 →(c) 排序 →(d) 畫面呈現。 每一塊都能單獨做、單獨確認對不對。一次只推一塊,壞了馬上知道是哪塊。</p><p><strong>③ 標出哪裡你有意見、哪裡放手</strong> 「排序邏輯我要管(這是產品核心)、畫面用框架預設就好(不是重點)」。 把你的判斷力花在真正重要的塊上,其餘讓 AI 自己決定 — 不必每行都管。</p><p><strong>④ 先做最小、能驗證的那一塊</strong> 不要一次要四塊。先做「能打一句話、回幾個結果」最小版,看到動了,再往上加。 看得到的進度比完美的計畫安全。</p><blockquote><p>心法:<strong>你拆得多細,AI 就做得多準。</strong> 含糊的大需求 → 含糊的大產出; 清楚的小塊 → 每塊都驗得過。這跟你帶一個很快但需要明確指示的新人,完全一樣。</p></blockquote><hr><h2 id="_6-你也可以照做-—-對-ai-下需求的五個心法" tabindex="-1">6. 你也可以照做 — 對 AI 下需求的五個心法 <a class="header-anchor" href="#_6-你也可以照做-—-對-ai-下需求的五個心法" aria-label="Permalink to &quot;6. 你也可以照做 — 對 AI 下需求的五個心法&quot;">​</a></h2><p>這套不只適用寫程式,用任何 AI 工具都成立:</p><p><strong>① 具體勝過抽象</strong> ✗ 「搜尋怪怪的」 ✓ 「搜『Michael Jackson』時第一名是一部戰爭片還標 100%,我預期它誠實說查不到」</p><p><strong>② 一次一件事</strong> 一則訊息一個主題。五個需求擠一則,AI 會全做但每個都打八折 —— 我們真實的教訓:四個改進一起上,整體變差還查不出誰的鍋;拆開一個一個來,才找到真正有效的那個。</p><p><strong>③ 給範例與反例</strong> 「標籤要像『紓壓』『虐戀』這種,不要『高共鳴策展』這種」—— 一組對照例勝過三段描述。</p><p><strong>④ 敢說「不對,我要的是…」</strong> AI 不會因為被打槍而變笨,只會因為你客氣而一直錯下去。 方向錯就直接打斷,愈早愈省。</p><p><strong>⑤ 重要的事,先要草稿</strong> 「先給我 draft,我們討論完再執行」—— 對外的訊息、要發布的文件、大的改動,都先看再放行。 這份指南本身,就是這樣來回三輪才定稿的。</p><hr><p><em>本指南內容取材自專案實際開發過程(2026-05 ~ 06),所有案例皆真實發生。</em></p>',48))])}const f=e(g,[["render",B]]);export{C as __pageData,f as default};
